import numpy as np

# Let me think about this differently - let's look at what happens to CONNECTED COMPONENTS
# of the pattern color (5)

def find_4cc(grid, color):
    """Find 4-connected components of a color"""
    height, width = grid.shape
    visited = np.zeros_like(grid)
    components = []

    for r in range(height):
        for c in range(width):
            if grid[r, c] == color and not visited[r, c]:
                comp = []
                queue = [(r, c)]
                visited[r, c] = 1
                while queue:
                    cr, cc = queue.pop(0)
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if grid[nr, nc] == color and not visited[nr, nc]:
                                visited[nr, nc] = 1
                                queue.append((nr, nc))
                components.append(comp)
    return components

